"""Local-filesystem storage for uploaded paper PDFs.

Layout under the configured root (PAPER_STORAGE_DIR):

    papers/YYYY/MM/<uuid4>.pdf          permanent files (key == relative path)
    .tmp/<hex>.part                     in-progress uploads (same volume -> atomic rename)
    .cleanup/pending-deletions.jsonl    files whose deletion failed; replayed by
                                        retry_pending_deletions()

Security model:
  * Keys are generated by the server only, and every key is checked against a
    strict allow-list pattern before it is turned into a path.
  * The resolved path must also stay inside the root (defence against symlinks).
  * Original filenames are never used on disk.
"""

import hashlib
import json
import logging
import os
import re
import threading
import uuid
from collections.abc import AsyncIterator, Awaitable, Callable
from dataclasses import dataclass
from datetime import UTC, datetime
from pathlib import Path
from typing import BinaryIO

from fastapi.concurrency import run_in_threadpool

logger = logging.getLogger(__name__)

CHUNK_SIZE = 1024 * 1024  # 1 MiB
TEMP_DIR_NAME = ".tmp"
CLEANUP_DIR_NAME = ".cleanup"
PENDING_DELETIONS_FILE = "pending-deletions.jsonl"

_UUID4 = r"[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}"
STORAGE_KEY_PATTERN = re.compile(rf"papers/\d{{4}}/(0[1-9]|1[0-2])/{_UUID4}\.pdf")

# Serialises writes to the cleanup ledger within this process.
_ledger_lock = threading.Lock()


class InvalidStorageKeyError(ValueError):
    """The key is not a server-generated key, or it would resolve outside the root."""


class UploadTooLargeError(Exception):
    def __init__(self, max_bytes: int) -> None:
        super().__init__(f"Upload exceeds {max_bytes} bytes.")
        self.max_bytes = max_bytes


class EmptyUploadError(Exception):
    pass


@dataclass(frozen=True)
class StagedFile:
    """A fully received, hashed and size-checked upload waiting in the temp area."""

    path: Path
    size_bytes: int
    sha256: str


@dataclass(frozen=True)
class CleanupReport:
    deleted: int
    already_missing: int
    still_failing: int
    invalid: int


class StorageService:
    def __init__(self, root: Path) -> None:
        self._root = Path(root).resolve()

    @property
    def root(self) -> Path:
        return self._root

    # --- keys and paths ----------------------------------------------------------

    @staticmethod
    def new_key(now: datetime | None = None) -> str:
        moment = now or datetime.now(UTC)
        return f"papers/{moment:%Y}/{moment:%m}/{uuid.uuid4()}.pdf"

    def resolve(self, key: str) -> Path:
        """Map a storage key to an absolute path inside the root, or raise."""
        if not isinstance(key, str) or not STORAGE_KEY_PATTERN.fullmatch(key):
            raise InvalidStorageKeyError("Invalid storage key.")
        path = (self._root / key).resolve()
        if not path.is_relative_to(self._root):
            raise InvalidStorageKeyError("Invalid storage key.")
        return path

    def exists(self, key: str) -> bool:
        try:
            return self.resolve(key).is_file()
        except InvalidStorageKeyError:
            return False

    # --- upload lifecycle --------------------------------------------------------

    async def stage(
        self,
        chunks: AsyncIterator[bytes],
        *,
        max_bytes: int,
        validate_header: Callable[[bytes], None],
        header_size: int,
    ) -> StagedFile:
        """Stream chunks into a temp file, hashing and size-checking as they arrive.

        validate_header() is called with the first `header_size` bytes before any of
        them are written, so non-PDF content is rejected immediately. On any failure
        (including cancellation) the temp file is removed and the error re-raised.
        """
        temp_dir = self._root / TEMP_DIR_NAME
        await run_in_threadpool(temp_dir.mkdir, parents=True, exist_ok=True)
        path = temp_dir / f"{uuid.uuid4().hex}.part"
        handle: BinaryIO = await run_in_threadpool(open, path, "xb")

        digest = hashlib.sha256()
        size = 0
        header = b""
        header_checked = False
        try:
            async for chunk in chunks:
                if not chunk:
                    continue
                size += len(chunk)
                if size > max_bytes:
                    raise UploadTooLargeError(max_bytes)
                if not header_checked:
                    header += chunk[: header_size - len(header)]
                    if len(header) >= header_size:
                        validate_header(header)
                        header_checked = True
                digest.update(chunk)
                await run_in_threadpool(handle.write, chunk)
            if size == 0:
                raise EmptyUploadError()
            if not header_checked:
                validate_header(header)  # file shorter than header_size
            await run_in_threadpool(_flush_and_sync, handle)
        except BaseException:
            # Synchronous cleanup: must also work while the task is being cancelled.
            handle.close()
            _unlink_quietly(path)
            raise
        handle.close()
        return StagedFile(path=path, size_bytes=size, sha256=digest.hexdigest())

    def commit(self, staged: StagedFile, key: str) -> Path:
        """Atomically move a staged file to its permanent key (same-volume rename)."""
        final = self.resolve(key)
        final.parent.mkdir(parents=True, exist_ok=True)
        if final.exists():
            raise FileExistsError("Storage key already in use.")
        os.replace(staged.path, final)
        return final

    @staticmethod
    def discard(staged: StagedFile) -> None:
        """Remove a staged temp file (no-op if it was already committed)."""
        _unlink_quietly(staged.path)

    def delete(self, key: str) -> bool:
        """Delete a stored file. Returns False if it was already gone.
        Raises InvalidStorageKeyError for non-server keys and OSError on I/O failure."""
        try:
            self.resolve(key).unlink()
        except FileNotFoundError:
            return False
        return True

    # --- deferred cleanup --------------------------------------------------------

    def record_pending_deletion(self, key: str, reason: str) -> None:
        """Append a key whose deletion failed, for retry_pending_deletions()."""
        ledger = self._ledger_path()
        entry = {"storage_key": key, "reason": reason, "recorded_at": datetime.now(UTC).isoformat()}
        with _ledger_lock:
            ledger.parent.mkdir(parents=True, exist_ok=True)
            with ledger.open("a", encoding="utf-8") as fh:
                fh.write(json.dumps(entry) + "\n")

    def pending_deletions(self) -> list[str]:
        ledger = self._ledger_path()
        if not ledger.is_file():
            return []
        keys = []
        for line in ledger.read_text(encoding="utf-8").splitlines():
            try:
                keys.append(json.loads(line)["storage_key"])
            except (ValueError, KeyError, TypeError):
                logger.error("Skipping malformed line in the pending-deletions ledger")
        return keys

    def retry_pending_deletions(self) -> CleanupReport:
        """Retry every queued deletion; keep only the ones that still fail."""
        deleted = missing = invalid = 0
        still_failing: list[str] = []
        with _ledger_lock:
            for key in dict.fromkeys(self.pending_deletions()):  # de-duplicate, keep order
                try:
                    if self.delete(key):
                        deleted += 1
                    else:
                        missing += 1
                except InvalidStorageKeyError:
                    invalid += 1
                    logger.error("Dropping invalid key from the pending-deletions ledger")
                except OSError:
                    still_failing.append(key)
            self._rewrite_ledger(still_failing)
        return CleanupReport(deleted, missing, len(still_failing), invalid)

    def _ledger_path(self) -> Path:
        return self._root / CLEANUP_DIR_NAME / PENDING_DELETIONS_FILE

    def _rewrite_ledger(self, keys: list[str]) -> None:
        ledger = self._ledger_path()
        if not keys:
            _unlink_quietly(ledger)
            return
        tmp = ledger.with_suffix(".jsonl.tmp")
        now = datetime.now(UTC).isoformat()
        tmp.write_text(
            "".join(json.dumps({"storage_key": k, "reason": "retry_failed", "recorded_at": now}) + "\n" for k in keys),
            encoding="utf-8",
        )
        os.replace(tmp, ledger)


def _flush_and_sync(handle: BinaryIO) -> None:
    handle.flush()
    os.fsync(handle.fileno())


def _unlink_quietly(path: Path) -> None:
    try:
        path.unlink(missing_ok=True)
    except OSError:
        logger.warning("Could not remove temporary file %s", path.name)


async def iter_upload_chunks(
    read: Callable[[int], Awaitable[bytes]], chunk_size: int = CHUNK_SIZE
) -> AsyncIterator[bytes]:
    """Adapt an async `read(size)` callable (e.g. UploadFile.read) into fixed-size chunks."""
    while True:
        chunk = await read(chunk_size)
        if not chunk:
            return
        yield chunk
